{
  "proposal": {
    "title": "住得近以后，谁支配省下的时间？城市到岗员工的午间离岗与下班留岗",
    "status": "建议保留为待验证的研究候选。两起独立事件足以提出问题。现有材料下，平均效应、作用机制和学术首创性均未知。",
    "01_event_comparison_and_conceptualization": {
      "E1": "据豆瓣帖主自述，其第一份工作期间从乘地铁改为步行通勤。后来换工作并住到公司步行约五分钟处时，能够午间回家做饭、午睡。帖主同时报告很少加班，并把下班后有更多个人时间归于工作安排和居住距离两个条件。依据为初始材料 S1 第43至46行。",
      "E2": "据另一名上班者的采访回忆，就近居住时容易在办公室多待，日常交往也多与附近同事重叠。后来搬远涉及购房预算、居住环境和工作生活边界偏好。其留岗时实际做了什么、是否受单位要求以及搬远前后工作分钟数的变化均未知。依据为初始材料 S2 第102至114行。",
      "comparison": "两案来自不同当事人和不同来源。可比部分是城市到岗员工在就近租住阶段所报告的时间安排。E1给出午间回家成为可行选项的线索，E2给出临近下班时可能延迟离开的线索。初始材料 S3 第653至705行只提供该商业调查样本内的住房偏好背景。",
      "concepts": "分别记录出行耗时、可用于特定活动的连续时段、员工对该时段的决定权，以及实际用途。决定权指员工能否发起、推迟或拒绝一项安排，并记录拒绝的实际后果。做饭、照护或与同事相处是否由员工自主选择，需要知道当次安排由谁提出、能否改期或拒绝。"
    },
    "02_question_and_counterexamples": {
      "question": "在工作地点、岗位和常规排班可比的城市到岗员工中，居住地点变化导致的通勤缩短，何时会使午休期间可以回家，何时会改变员工接受临时留岗请求的概率？两种变化如何共同影响员工实际能自行安排的时间？",
      "baseline_and_event_challenge": "基准预期是，工作和家庭义务保持稳定时，通勤耗时下降会扩大可自行安排的时间。E2对这一预期提出反诘，但办公室久留的用途、起因和时长未知，因此目前属于待核验的反例线索。",
      "counterexamples_to_seek": [
        "午休可离岗且往返已能容纳一项事先想做的活动，员工仍没有增加午间回家的频率。应核对活动偏好、替代地点和家庭义务，再判断可达性预测是否成立。",
        "对同一员工，在岗位、工作量和临时请求类型相近时，搬近提高了接受请求的可行性，但接受率和实际离岗时间均无变化。此结果会削弱通勤距离通过临时留岗影响时间分配的解释。",
        "同一员工搬近后，午间回家更频繁，傍晚也更常因临时请求留岗。应据完整工作日记录判断两种变化的净结果。"
      ]
    },
    "03_issue_positioning": "将候选放在劳动时间分配与工作生活边界的交叉处。住房选择解释员工如何进入不同的通勤条件，组织规则和临时任务解释时间窗口能否由员工使用。主分析单位为员工工作日，机制分析单位为一次午间离岗机会或一次临时留岗请求。",
    "04_literature_dialogue": {
      "object": {
        "evidence": "Wang、Gong 与 Wang（2020）研究中国城市通勤时间与劳动供给。正文式（11）及其后说明将日工时、每周工作天数和周工时作为结果，并讨论通勤与工作选择的内生性。",
        "location": "第2节式（11）及第3.1节开头，网页第286至306行。",
        "dialogue": "沿用其对工时层次和内生性的区分。进一步追问同样的日工时是否掩盖了午间离岗和傍晚临时留岗的不同变化。搬家前后若同时换岗，固定效应也无法直接区分这两项改变。",
        "url": "https://www.mdpi.com/1660-4601/17/13/4631"
      },
      "issue": {
        "evidence": "Giménez-Nadal 与 Velilla 的英国时间使用研究使用2015年工作日活动日记，区分有酬劳动、无酬劳动和休闲。附表11比较多种居家办公定义。",
        "location": "附表11，PDF印刷页27至28，网页提取版第2452至2635行。",
        "dialogue": "既有研究已经按多种用途考察工作日时间分配。将居家办公作为情境对照时，需要保留其工作地点变化这一条件。本候选观察持续到岗的员工，比较省时发生在什么时段，以及该时段由谁安排。",
        "url": "https://www.econstor.eu/bitstream/10419/318031/1/10663_2023_Article_9590.pdf"
      },
      "theory": {
        "dialogue": "以角色边界视角提出两条可区分的推论。午间，往返耗时下降后，获准离岗的员工可能首次来得及完成原来做不了的居家活动。傍晚，在临时请求出现、离岗可协商且员工有固定到家时点的情况下，较短的回家路程可能使员工赶得及在处理请求后按时到家，从而提高留岗接受率。前一条推论针对活动能否进入日程，后一条针对组织能否使用同一员工的时间。两条推论均属本轮推演。",
        "verification": "理论检索定位到角色微转换与边界控制相关文献。本轮可核对的页面内容不足以确定这些文献是否已提出同样的联合预测，理论优先性未知。"
      }
    },
    "05_abstraction_and_context_transfer": {
      "abstract_relation": "当两个活动地点之间的移动耗时下降，个人可行的活动范围可能扩大。在同一时段也可被组织调度时，最终由谁使用这段时间，取决于活动所需的连续时长、已承诺的结束时点和变更安排的决定权。",
      "transfer_test": "可在工作地与固定接送点之间检验同一推论。若路程缩短后员工首次能在固定接送时点前完成一件自选事务，同时也更常接受此前来不及处理的临时工作请求，就能检验两种变化能否并存。接送义务及其截止时点须单独记录。这是对适用范围的检验。"
    },
    "06_competing_explanations": [
      {
        "explanation": "岗位工作量或主管要求",
        "discriminating_observation": "比较同人同岗、任务量和排班相近的工作日，分别记录临时请求次数与收到同类请求后的接受率。若变化主要随请求增多或强制留岗出现，优先考虑工作需求解释。"
      },
      {
        "explanation": "对工作和生活边界的偏好先于住房选择",
        "discriminating_observation": "用搬家前的住房备选、计划和既有离岗习惯确定时间顺序。若留岗变化早于搬家，或主要集中在因边界偏好主动搬家的人，住房自选解释更有力。"
      },
      {
        "explanation": "同事交往机会或主动选择与同事为邻",
        "discriminating_observation": "分别记录实际工作、办公室内非工作活动和下班后同事社交。在距离相近的员工中比较同事居住分布和社交邀请。若只见社交重叠变化，支持社会交往路径。"
      },
      {
        "explanation": "住房预算、品质或家庭安排随搬家一起变化",
        "discriminating_observation": "记录租购变化、住房条件及家庭照护安排。若新增时间主要用于同期新增的家务或照护，或变化只见于居住品质显著改善者，应检验住房与家庭义务的解释。"
      }
    ]
  },
  "evidence_urls": [
    "https://www.mdpi.com/1660-4601/17/13/4631",
    "https://www.econstor.eu/bitstream/10419/318031/1/10663_2023_Article_9590.pdf"
  ],
  "academic_increment": {
    "candidate_increment": "提出一条可检验的条件性命题。对持续到岗的同一员工，通勤缩短可以同时扩大午间的自主活动机会，并提高傍晚接受临时留岗的概率。前者取决于午间离岗许可和活动所需时长，后者取决于可协商的临时请求以及到家截止时点。即使日总工时变化很小，两个时段的支配权也可能分别变化。",
    "required_evidence": "需要发现与两条预测各自吻合的过程证据，并显示它们可以在同一员工身上并存。若差异主要随工作量、住房自选或家庭义务变化，或最接近的文献已经提出同样的条件和预测，当前学术增量不成立。",
    "current_judgment": "增量是待验证的解释命题。换城市、换人群、重命名和细化日记指标本身均不足以成立。"
  },
  "feasibility": {
    "available_now": "两案、商业调查样本的住房偏好和两项已核对的研究材料，可支持前期问题定义与研究设计。两案均缺少日记、考勤或独立证词，材料也未提供可联系的研究样本。",
    "minimum_design": "围绕不换岗的住房搬迁招募到岗员工，在搬迁前后连续记录可比工作日。设置同期未搬家且岗位与排班相近的比较员工。日记需记录实际通勤、午休长度及离岗许可、临时请求及其发起人、能否拒绝、实际离岗时间、活动用途、到家截止时点和家庭义务。经同意，可用排班或考勤交叉核对时间。分别检验午间活动首次变得可行、同类请求的条件接受率及全天时间分配。",
    "decision_gate": "组织和员工招募、前瞻日记、可比搬迁样本及辅助记录的获取均未知。若只能取得回顾性访谈，可做过程比较。要估计通勤缩短的因果效应，还需找到可辩护的变动来源，并核对其是否同时改变岗位、排班或住房条件。"
  },
  "limitations": [
    "E1的首份工作搬近和后来换岗后的五分钟步行属于不同阶段。E2的办公室久留及搬远理由属于回顾性陈述，搬远还涉及租购转换。两案无法给出效应量、发生率或因果方向。",
    "既有研究与初始商业调查无法交叉核实个案。研究候选沿用事件编号，初始公开页面仍可能识别当事人。",
    "本轮按查询和页面打开分别计数，共发起12个联网动作。evidence_urls只列出返回了可定位内容且用于本提案的新增页面。理论页面的可定位证据未核得，文献覆盖与首创性仍待确认。"
  ]
}
